-- Columns dropped from brz_supplier:
--   s_comment                    free-text filler generated by TPC-H, no analytical value
--   _batch_id, _source_relation  Bronze audit metadata: lineage questions are answered in Bronze;
--                                _loaded_at is kept (used by deduplicate and as freshness marker)

with source as (
    {{ deduplicate(ref('brz_supplier'), partition_by=['s_suppkey']) }}
)

select
    -- keys
    s_suppkey::varchar                                  as supplier_id,
    s_nationkey::varchar                                as nation_id,

    -- attributes
    trim(s_name)::varchar                               as supplier_name,
    trim(s_address)::varchar                            as supplier_address,
    trim(s_phone)::varchar                              as phone,
    split_part(trim(s_phone), '-', 1)::number(38, 0)    as phone_country_code,

    -- measures
    s_acctbal::number(12, 2)                            as account_balance,
    s_acctbal < 0                                       as has_negative_balance,

    _loaded_at
from source
